draw:
var pad = 44, x0 = pad, x1 = W - 14, yb = H - 26, yt = 16;
var xlim = 0.5;
var n = p.n;
function X(v) { return x0 + ((v + xlim) / (2 * xlim)) * (x1 - x0); }
var lo = Math.min(Math.pow(1 - xlim, n), Math.pow(1 + xlim, n), 1 - n * xlim, 1 + n * xlim);
var hi = Math.max(Math.pow(1 - xlim, n), Math.pow(1 + xlim, n), 1 - n * xlim, 1 + n * xlim);
var span = Math.max(hi - lo, 0.4), mid = (hi + lo) / 2;
var vlo = mid - span * 0.62, vhi = mid + span * 0.62;
function Y(v) { return yb - ((v - vlo) / (vhi - vlo)) * (yb - yt); }
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, yt); ctx.lineTo(x0, yb); ctx.lineTo(x1, yb); ctx.stroke();
ctx.fillStyle = C.faint;
for (var d = -0.5; d <= 0.5001; d += 0.25) {
  ctx.beginPath(); ctx.moveTo(X(d), yb); ctx.lineTo(X(d), yb + 4); ctx.stroke();
  ctx.fillText(d.toFixed(2), X(d) - 12, yb + 17);
}
ctx.fillText("x", (x0 + x1) / 2 - 3, yb + 17 + 0);
ctx.fillText(vhi.toFixed(2), 6, Y(vhi) + 10);
ctx.fillText(vlo.toFixed(2), 6, Y(vlo) - 2);

// true curve
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.8;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var xx = -xlim + 2 * xlim * i / 120;
  var yy = Math.pow(1 + xx, n);
  if (i === 0) ctx.moveTo(X(xx), Y(yy)); else ctx.lineTo(X(xx), Y(yy));
}
ctx.stroke();

// tangent line
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.8; ctx.setLineDash([5, 4]);
ctx.beginPath();
ctx.moveTo(X(-xlim), Y(1 - n * xlim));
ctx.lineTo(X(xlim), Y(1 + n * xlim));
ctx.stroke(); ctx.setLineDash([]);

ctx.fillStyle = C.ink; ctx.fillText("(1+x)ⁿ", X(0.22), Y(Math.pow(1.22, n)) - 8);
ctx.fillStyle = C.accent; ctx.fillText("1 + nx", X(-0.46), Y(1 - n * 0.46) + 16);

// the reader's point, with a pulsing error bar
var xs = p.x;
var exact = Math.pow(1 + xs, n), approx = 1 + n * xs;
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(xs), yt); ctx.lineTo(X(xs), yb); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5 + 1.5 * (0.5 + 0.5 * Math.sin(2 * t));
ctx.beginPath(); ctx.moveTo(X(xs), Y(exact)); ctx.lineTo(X(xs), Y(approx)); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(xs), Y(exact), 3.5, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(xs), Y(approx), 3.5, 0, 6.2832); ctx.fill();

var err = exact === 0 ? 0 : (approx - exact) / exact * 100;
out.note = "n = " + n.toFixed(2) + ", x = " + xs.toFixed(2) +
  ":  exact " + exact.toFixed(4) + ",  1+nx = " + approx.toFixed(4) +
  ",  error " + err.toFixed(2) + "%";
